from collections import deque

def route(graph, start, goal):
    prev = {start: None}
    queue = deque([start])
    while queue:
        v = queue.popleft()
        for nxt in graph[v]:
            if nxt not in prev:
                prev[nxt] = v
                queue.append(nxt)
    path = []
    while goal is not None:
        path.append(goal)
        goal = prev[goal]
    return path[::-1]

